-- ============================================================
-- 여기찜 · 더미 데이터를 실제 가게로 교체
-- ============================================================
-- 전에 실행한 saved-places-dummy-seed.sql은 "을지로 우동집" 같은
-- 가상의 가게 이름을 썼습니다. 이 스크립트는 그 가짜 20곳(kakao_place_id
-- 가 D001~D020)을 지우고, 카카오 로컬 API로 직접 조회한 실제 상호명
-- 20곳으로 다시 채웁니다. 더미 저장자 10명(dummy_seed_*@yeogijjim.test)은
-- 이미 만들어져 있으니 그대로 재사용합니다.
-- Supabase 대시보드 > SQL Editor에서 실행하세요.
-- ============================================================

-- 1) 가짜 더미 가게(D001~D020) 삭제
delete from saved_places where kakao_place_id ~ '^D0[0-9]{2}$';

-- 2) 실제 가게 20곳으로 재삽입
with dummy_users as (
  select id, row_number() over (order by email) as rn
  from auth.users
  where email like 'dummy_seed_%@yeogijjim.test'
),
