)
insert into saved_places (user_id, kakao_place_id, place_name, category_name, address, lat, lng, place_url, phone)
select du.id, p.kakao_place_id, p.place_name, p.category_name, p.address, p.lat, p.lng, p.place_url, p.phone
from places p
join dummy_users du on du.rn <= p.weight
on conflict (user_id, kakao_place_id) do nothing;
